        if self.has_bias:
            bias = self.conv_transpose3d.bias.contiguous()
        else:
            bias = torch.zeros(self.out_channels, dtype=x.dtype, device=x.device)

        x = x.contiguous()
        output = torch.empty((B, self.out_channels, D_out, H_out, W_out), dtype=x.dtype, device=x.device)

        module = _get_ptx_module()
        N = B * self.out_channels * D_out * H_out * W_out
