        assert self.stride == (1, 1, 1) and self.padding == (0, 0, 0) and self.output_padding == (0, 0, 0)
        assert self.groups == 1

        D_out = (D - 1) * sD - 2 * pD + kD + opD
        H_out = (H - 1) * sH - 2 * pH + kH + opH
        W_out = (W - 1) * sW - 2 * pW + kW + opW

        weight = self.conv_transpose3d.weight.contiguous()
        if self.has_bias:
            bias = self.conv_transpose3d.bias.contiguous()
        else:
            bias = torch.zeros(self.out_channels, dtype=x.dtype, device=x.device)

        x = x.contiguous()
        output = torch.empty((B, self.out_channels, D_out, H_out, W_out), dtype=x.dtype, device=x.device)

        module = _get_ptx_module()
        N = B * self.out_channels * D_out * H_out * W_out
        threads = 256
        blocks = (N + threads - 1) // threads

        module.launch(
            "convtranspose3d_kernel",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, weight, bias, output],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output
